import org.formasaloido.*;
import java.util.*;

public final class OrientationChecks {
 static int checks;static void check(boolean ok,String message){checks++;if(!ok)throw new AssertionError(message);}
 static void near(double actual,double expected,String message){check(Math.abs(actual-expected)<.001,message+": "+actual);}
 public static void main(String[] args)throws Exception{
  Sound.Settings settings=new Sound.Settings();settings.spatial=2;
  Sound.Program p=new Sound.Program(settings).moveTimed(new Geometry.Point(0,0),new Geometry.Point(300,225),5).silence(1).moveTimed(new Geometry.Point(300,225),new Geometry.Point(600,450),5);
  Sound.Renderer r=new Sound.Renderer(null);short[] pcm=new short[Sound.RATE*2];
  check(r.control("pause").contains("No hay"),"no stale playback at startup");r.program(p);r.render(pcm,Sound.RATE,settings);near(r.seconds(),1,"one second rendered");
  r.control("mark");check(r.paused(),"mark pauses for spoken feedback");Arrays.fill(pcm,(short)123);r.render(pcm,Sound.RATE,settings);near(r.seconds(),1,"paused cursor does not drift");for(short sample:pcm)if(sample!=0)throw new AssertionError("paused PCM must be silent");checks++;
  r.control("resume");for(int i=0;i<6;i++)r.render(pcm,Sound.RATE,settings);near(r.seconds(),7,"resume retains original cursor");r.control("back");near(r.seconds(),2,"rewind five seconds");check(r.paused(),"rewind pauses");r.control("return");near(r.seconds(),1,"bookmark restored exactly");
  r.control("fragment");near(r.seconds(),0,"fragment seeks to current span start");for(int i=0;i<6;i++)r.render(pcm,Sound.RATE,settings);near(r.seconds(),1,"repeat ends at original cursor");check(r.paused(),"fragment does not play next span");check(!r.done(),"fragment pause is not whole completion");
  r.control("resume");for(int i=0;i<4;i++)r.render(pcm,Sound.RATE,settings);r.render(pcm,Sound.RATE/2,settings);check(r.control("position").contains("Pausa entre señales"),"silence described as gap");r.control("resume");r.render(pcm,Sound.RATE,settings);check(r.control("position").contains("Segmento sonoro 2"),"current span described after gap");
  r.program(p);check(r.control("return").contains("Todavía"),"new playback invalidates marker");r.control("back");near(r.seconds(),0,"rewind clamps at zero");r.control("mark");r.control("fragment");for(int i=0;i<6;i++)r.render(pcm,Sound.RATE,settings);near(r.seconds(),5,"repeat from start previews first five seconds");r.control("return");near(r.seconds(),0,"zero bookmark is valid");r.control("resume");for(int i=0;i<12;i++)r.render(pcm,Sound.RATE,settings);check(r.done(),"full playback finishes");r.control("fragment");near(r.seconds(),6,"repeat at completed end seeks last five seconds");for(int i=0;i<6;i++)r.render(pcm,Sound.RATE,settings);near(r.seconds(),11,"repeat never runs past program end");check(r.paused(),"repeat at end pauses");r.touch(new Geometry.Point(10,10),"line");check(r.control("return").contains("No hay"),"direct exploration cancels stored playback");r.quiet();check(!r.paused(),"stop clears pause");
  Geometry g=new Geometry(0,Arrays.asList(new Geometry.Shape(Curriculum.points(100,100,500,100,500,350,100,350),true,false),new Geometry.Shape(Curriculum.points(300,200),false,false),new Geometry.Shape(Curriculum.points(200,200,220,200,220,220),true,false,3,true)));
  String overview=Orientation.overview(g);check(overview.contains("1 puntos aislados, 0 trazos abiertos, 1 contornos cerrados y 1 huecos"),"overview distinguishes holes and points");check(Orientation.at(g,new Geometry.Point(100,225)).contains("a 0 unidades"),"distance includes closing edge");check(Orientation.at(g,new Geometry.Point(-1,0)).contains("Fuera"),"outside canvas distinct");check(Orientation.overview(new Geometry(0,Collections.<Geometry.Shape>emptyList())).contains("no contiene"),"empty overview");
  TraceDrawing d=new TraceDrawing();d.coordinate(10,20,true,"Autor");d.coordinate(50,20,false,"");d.coordinate(50,80,false,"");check(d.pointCount()==3&&d.strokes().size()==1,"coordinate editing joins selected last path");check(d.strokes().get(0).samples().get(2).time==2000,"synthetic timing explicit");check(d.strokes().get(0).label.equals("Autor"),"label kept");check(TraceDrawing.decode(d.encode()).pointCount()==3,"coordinate project portable");int count=d.pointCount();try{d.coordinate(Double.NaN,0,true,"");throw new AssertionError("invalid accepted");}catch(IllegalArgumentException expected){}check(d.pointCount()==count,"invalid edit atomic");d.strokes().get(0).closed=true;try{d.coordinate(100,100,false,"");throw new AssertionError("closed extension accepted");}catch(IllegalStateException expected){}check(d.pointCount()==count,"closed path not silently changed");d.undo();check(d.pointCount()==0,"undo coordinate stroke");
  System.out.println("PASS "+checks+" orientation/transport/authoring checks.");
 }
}
